INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-001', 'sony-wh1000xm6', 'pro_review', 'What Hi-Fi?', 'https://www.whathifi.com/headphones/sony-wh-1000xm6', 'Andy Madden', '2025-05-15', '{"value":5.0,"scale":5.0}'::jsonb, 'Sony WH-1000XM6 review: a sensational performance upgrade | What Hi-Fi?', 'What Hi-Fi? Awards 2025 winner. Can Sony''s new flagship wireless headphones set a new standard? […] Quick Attention Mode is also back, which allows you to hear ambient sounds straight away by placing a hand on the exterior of the right earcup – useful if you’re expecting an announcement on a train platform or at an airport terminal and just want to check in occasionally. […] Sony’s wireless headphones deliver a performance more than befitting a flagship pair of wireless headphones. Comfort levels are great, they’re nice to use, ANC is excellent, call quality is class-leading, and sound quality can match anything at this level. Simply sensational. […] Battery life for the WH-1000XM6 remains identical to the previous generation at 30 hours with Bluetooth and active noise cancelling (ANC) both turned on. The fact that there hasn’t been an increase doesn’t come as a major surprise given the introduction of a more powerful processor. […] In those three years, Sony has been very busy behind the scenes. Design, features, sound quality, noise cancelling, call quality. You name it, Sony has revisited it for the WH-1000XM6 to try and keep one step ahead of the competition.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-002', 'sony-wh1000xm6', 'pro_review', 'TechRadar', 'https://www.techradar.com/audio/wireless-headphones/sony-wh-1000xm6-review', 'Harry Padoan', '2025-05-15', '{"value":4.5,"scale":5.0}'::jsonb, 'Sony WH-1000XM6 review: excellent headphones that meld the best parts of Sony''s previous cans | TechRadar', 'The best of the XM4 and XM5 in one new pair of cans […] There’s an evolution of what came before too, with a wider headband for increased comfort and a more snug fit around the neck when the headphones are out of use. Overall, you’re getting a fantastic combination of style and comfort, though some may still feel that the earcups are a tad chunky. […] You get slightly better ANC from the Sony XM6, plus I found the Sony cans to be more comfortable – but if we’re talking pure sound, you could do a little better for the same price. […] Still, there are a few areas in which the WH-1000XM6 fall just short of their rivals. You get 30 hours of battery life with ANC, which is by no means bad, but lots of rivals (even much cheaper ones) beat that, and some can double it. […] The new QN3 processor also harnesses the power of 12 microphones – four more than last time – to serve up truly incredible noise cancelling capabilities. These supply better ANC than the majority of the best noise cancelling headphones out there. Yes, they even stand up to the critically acclaimed Bose QuietComfort Ultra Headphones , which have ruled the noise cancelling roost since their launch. When on public transpor…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-003', 'sony-wh1000xm6', 'pro_review', 'SoundGuys', 'https://www.soundguys.com/sony-wh-1000xm6-review-read-before-buying-137397/', 'Christian Thomas', '2025-12-11', '{"value":8.3,"scale":10.0}'::jsonb, 'Sony WH-1000XM6 review: It (mostly) delivers - SoundGuys', 'The latest update to the most popular ANC headphones is here, but are they any good? Find out in our Sony WH-1000XM6 review. […] But my main issue is that the ANC mic protrudes a couple of millimeters from the mesh plane, and can easily touch your ear if you don’t get a great seating right off the bat. One of my colleagues even had it rub a bit on his ears, which can be a little annoying. Normally, I wouldn’t be too hard on something like this, but you can affect your results if your tragus presses into this little bit. […] My biggest gripe with the Sony WH-1000XM6 is the comfort, which is a tough thing to contextualize because of how different everyone’s ears are. The wider band structure is more accommodating to larger heads without leaving smaller noggins out in the cold, but the pads are relatively thin compared to what many might prefer. Though I will always gripe about thin ear pads, the material grips to skin fairly well, and the mesh is loose enough to avoid putting too much pressure on your ears. […] Product maintenance is a bit of a question mark, though the pads are easy to remove in the event that you need to clean them. Just grab the top of the earpads and firmly start…', true, 'But my main issue is that the ANC mic protrudes a couple of millimeters from the mesh plane, and can easily touch your ear if you don’t get a great seating right off the bat.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-004', 'sony-wh1000xm6', 'pro_review', 'AVForums', 'https://www.avforums.com/reviews/sony-wh-1000xm6-wireless-headphone-review.22795/', NULL, NULL, NULL, 'Sony WH-1000XM6 Wireless Headphone Review  | AVForums', 'Review of Sony''s WH-1000XM6 wireless headphone, the company''s latest update to its successful 1000XMx series of ANC headsets […] You of course are not me however. You should know that this is the best active noise cancelling I have ever tested and that there are sonic tweaks to keep you entertained on a long haul flight to… well… pretty much anywhere. This is cleverest, most customisable and most flexible wireless headphone that money can buy. For many people any foibles in the way it presents that cleverness will be meaningless in comparison to that simple statement of fact and for that reason the Sony comes Highly Recommended. […] As a piece of industrial design, the XM6 feels different too. It’s a mass of soft touch, matte finish materials that give it a curiously organic sense at some points. It’s well made and the fact it folds is handy (although don’t go thinking that the result is significantly smaller to the PX7 S3 once it is in its case because it really isn’t) but as a piece of industrial design I prefer the Bowers. Three finishes are available; the ‘Platinum Silver’ of the review samples, Black and Midnight Blue. Overall build and finish are entirely up to the standards…', true, 'You should know that this is the best active noise cancelling I have ever tested and that there are sonic tweaks to keep you entertained on a long haul flight to… well… pretty much anywhere.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-005', 'sony-wh1000xm6', 'pro_review', 'WIRED', 'https://www.wired.com/review/sony-wh-1000xm6/', 'Parker Hall', '2025-05-15', '{"value":9.0,"scale":10.0}'::jsonb, 'Sony WH-1000XM6 Review: The Best Noise-Canceling Headphones | WIRED', 'The Japanese flagship headphones come with seven times the processing power, new drivers, and the best noise-canceling we’ve ever tested. […] I didn’t have time to take these on a flight during my short review period, but I did play hours of plane and HVAC noises at real-world decibels through my studio monitors while listening to music on them, and they proved to be more capable than any headphones I’ve ever tested in dealing with those sounds. It’s almost shocking how well they do with a low hum like that of a robovac —I kept accidentally bumping into the moving puck on my floor when wandering around the house with these on, forgetting it was active at all. […] The earpads aren’t the most comfortable things in the world, especially when compared to higher-end offerings like the Focal Bathys MG ( 9/10, WIRED Recommends ), which come with such fine leather you’d imagine it being sewn into King Charles’ dress shoes. These are somewhat cheap-feeling and rubbery faux leather, but they do have very comfortable memory foam that ensures a soft seal around your ears. The non-leather is a good choice for durability and is shockingly resistant to sweat, which I found out while spreading a f…', true, 'I didn’t have time to take these on a flight during my short review period, but I did play hours of plane and HVAC noises at real-world decibels through my studio monitors while listening to music on them, and they prove', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-006', 'sony-wh1000xm6', 'pro_review', 'Eurogamer', 'https://www.eurogamer.net/after-18-hours-flying-economy-with-sonys-wh-1000xm6-i-may-just-have-a-new-favourite-pair-of-anc-headphones', 'Reece Bithrey', '2025-11-16', NULL, 'After 18 hours flying economy with Sony''s WH-1000XM6, I may just have a new favourite pair of ANC headphones | Eurogamer.net', 'The Sony WH-1000XM6 are a brilliant pair of wireless headphones with gorgeous audio, optimal noise cancellation and a comfy fit that''s ideal for air travel. […] There''s been a lot of travelling I''ve had to do this year - my first Gamescom in Cologne, press trips to Europe by plane and train, and the big family holiday to Florida. Nine hours each way on a plane with a busy Virgin Atlantic Economy cabin can be tiring at the best of times, so I wanted a pair of headphones I could rely on to get shot of as much noise as possible. Initially, I weighed up between my trusty Focal Bathys or the Nothing Headphone (1) that I''d taken to Cologne, although when the Sony WH-1000XM6 landed at my doorstep a few days before, it seemed like the ideal opportunity to test them. […] The redesigned chassis makes the XM6s an easy headphone to travel with, especially with its folding stainless steel hinges. Sony has also made the headband wider and flatter than with the XM5s, resulting in improved comfort and a tighter clamping force for a stronger seal for ANC and improved passive isolation. At 254g, the XM6s are lightweight, especially against some rivals that push over 300g, and even on those lengthy f…', true, 'There''s been a lot of travelling I''ve had to do this year - my first Gamescom in Cologne, press trips to Europe by plane and train, and the big family holiday to Florida.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-007', 'sony-wh1000xm6', 'reddit', 'Reddit r/SonyHeadphones', 'https://www.reddit.com/r/SonyHeadphones/comments/1l11771/longish_term_review_xm6/', NULL, NULL, NULL, 'Long(ish) Term Review XM6', 'As mentioned in a reply to an earlier post, I recently returned from a two week work trip where I logged roughly 37 hours in the air (so with airport and tarmac time, closer to 45 hours of wear time). … On the various flights, the time was roughly an hour to as many as 13+ (Dulles to Ethiopia was a haul). … ANC: Top notch. Never once had an issue with the drone of the plane engines or other repetitive noises that are common while traveling. While I wish it could have muted the inconsiderate folks that were talking at a very high volume (so much so the entire plane could hear them), I realize that’s not how the ANC works. That said, even with those folks talking loudly, the headphones did a nice job of at least dampening their voices so I could focus on what I was listening to. … especially considering I wear glasses … Battery Life: Crazy good. For my flight to Ethiopia, I had them on for easily 14 hours straight (in addition to listening off and on before boarding). By the time I landed, I had 58% battery life left and that’s with ANC on the whole time. Absolutely zero complaints in this department. … In closing, overall, I’m very happy with the headphones and will gladly continue…', true, 'I recently returned from a two week work trip where I logged roughly 37 hours in the air … especially considering I wear glasses', 'Reddit blocks automated fetches (403). Text = verbatim fragments of the post as shown in a web-search index on 2026-09-25, joined with …; author/date not visible. Re-fetch manually for full text.', '2026-09-25', '["Partial text only (search-index excerpt)"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-008', 'sony-wh1000xm6', 'other', 'Travels with Tech (blog)', 'https://travelswithtech.com/2025/08/06/sony-wh-1000xm6-review-best-headphones-for-frequent-flyers/', NULL, '2025-08-06', NULL, 'Travels with Tech | Sony WH-1000XM6 Review: Best Headphones for Frequent Flyers?', 'When I pack for a trip, there are a few essentials that always make it into my carry-on. A solid pair of active noise cancelling (ANC) headphones is at the top of that list. Since Sony surprised th… […] Sony has addressed one of my biggest issues with the previous generation, comfort. The WH-1000XM6 features a wider, better-padded headband, eliminating the top-band discomfort I experienced with the XM5 after a few hours. The slight redesign in the curvature also reduces pressure on the ears. Whether you’re using these on a long-haul flight or during a full workday abroad, they’re among the most comfortable ANC headphones I have worn. […] When I pack for a trip, there are a few essentials that always make it into my carry-on. A solid pair of active noise cancelling (ANC) headphones is at the top of that list. Since Sony surprised the market in 2016 with the MDR-1000X, they’ve consistently delivered some of the best ANC headphones available. Nine years later the market is more competitive than ever. Sony’s latest model WH-1000XM6 continues to push the bar forward with meaningful updates in comfort, portability and smart travel-friendly features. […] All of this is say, the WH-1000XM6…', true, 'Whether you’re using these on a long-haul flight or during a full workday abroad, they’re among the most comfortable ANC headphones I have worn.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-009', 'sony-wh1000xm6', 'other', 'Tim Stevens: Million Miler Review (blog)', 'https://www.timstevens.me/p/sony-wh-1000xm6-long-term-review', 'Tim Stevens', '2026-06-12', NULL, 'Million Miler Review: My Sony WH-1000XM6 were the ultimate travel headphones, until they broke', 'And so, committing to buy a set of Sony WH-1000XM6 (henceforth just XM6) headphones, given their eye-watering $450 price and considerable size, was not a decision I made lightly. But buy them I did, and I loved them too. They’ve been around the world with me countless times. And then, 308 days after I put them into service, they broke. […] A lot of headphones bind uncomfortably, but I was immediately impressed at how well the XM6 fits my head. Yes, I need to extend those arms all the way, but the lightweight construction and the foam padding on the headband make for something that''s quite comfortable to wear for hours and hours at a time. […] This is, sadly, where it all falls apart. Before I bought these, I read up on their predecessors, the XM5. They got almost universal praise, but I read a few instances of people suffering broken hinges. Though I was early in getting my XM6 headphones after their release last year, there were already a few reports of similar failures. […] Just this past week I noticed the right extension area on the top had cracked, a loop of plastic. At first I thought it was just cosmetic, no big deal, but I quickly realized it serves a functional purpose. Wi…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCL