INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-010', 'sony-wh1000xm6', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/69b62620e4b075f9f9ec2f3a//69df3c31e4b08a305ee87c00/', NULL, '2026-04-15', '{"value":5,"scale":5}'::jsonb, NULL, 'I used the XM3s for 7 years, only upgraded because they started breaking down. The XM6s are better in every way. I use them daily and can''t do anything but recommend them. If you think that cheaper headphones have "Active Noise Cancelling", you are wrong. The noise cancelling from these headphones is incredible, and they are so comfortable to wear, I basically only take them off when people talk to me. These are well worth the money. The only gripe I have with them is that they don''t have real buttons, they use touch gestures which don''t always work.', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
