INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-014', 'sony-wh1000xm6', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/69d1d577e4b069dfb52b58fd/null/69f8339ce4b0451a9458873d/', 'Debbie', '2026-05-04', '{"value":4,"scale":5}'::jsonb, NULL, 'For the price, felt very ‘plasticy’ and not good quality so returned for AirPod max which are far better quality & sound', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
