INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-018', 'sony-wh1000xm6', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/6a93a228e4b0df765c6c78fe//6ab4e553e4b05766598e2aac/', NULL, '2026-09-24', '{"value":5,"scale":5}'::jsonb, NULL, 'The Sony headphones are very good, literally so quiet. Not able to hear any noise just my music!', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-019', 'sony-wh1000xm6', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/6a84265460b2151e56b854bd/null/6a84265460b2151e56b85512/', 'pete the pilot', '2026-08-10', '{"value":5,"scale":5}'::jsonb, NULL, 'The case is good, if a little fiddly to use until you get used to it. The headphones are a little warm around the ears to wear, but connect flawlessly every time with my phone.  They are bulky, but light and comfortable to wear for long periods. I wear specs all the time and thankfully the sidearms are flat so they don''t leave gaps in the cushions for noise to leak through. Noise cancelling is phenomenal! I always have the sound at a low level & cannot hear anything external except for sharp sudden noises which are very diminished by the time they reach my ears. They basically act as superb ear defenders. I''ve used them with routers, saws and drills and honestly can''t hear much, if anything, at all. I get a lot of grief from my wife because I can''t hear a word she says and she has a fairly loud voice! It''s very simple though to press against the right ear plate to temporarily listen to something or someone. I have learnt to have ambient mode selected when outdoors, otherwise I can''t hear loud vehicles at all. Wind noise can be a bit irritating under those circumstances if it is blowing a strong breeze, but it''s a small price to pay to be safe.  The sound quality is superb. I''m play…', true, NULL, NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-020', 'sony-wh1000xm6', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/6a6215e360b2e4025ae96a10/null/6a6215e360b2e4025ae96a4b/', 'skowronskiphoto', '2026-06-20', '{"value":5,"scale":5}'::jsonb, NULL, 'I rocked my WH-1000XM3s for six solid years and thought ANC headphones couldn''t get much better. I was wrong. I am completely astonished by how much of a leap the WH-1000XM6s are. Sony finally brought back the folding hinges, making them beautifully compact for travel again. The noise cancellation is next-level, completely erasing high-pitched background chatter that my XM3s couldn''t quite block. The sound is noticeably richer with deeper, cleaner bass, and the seamless multipoint Bluetooth switching is a massive quality-of-life upgrade. They also feel lighter and more comfortable during long sessions. If you''ve been holding onto an older pair wondering if the upgrade is worth it-it absolutely is. 5/5 stars.', false, NULL, NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-021', 'sony-wh1000xm6', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/6968f82160b2bcf765c28497/null/6968f82160b2bcf765c2850e/', 'Matt9753', '2025-11-29', '{"value":3,"scale":5}'::jsonb, NULL, 'The audio technology is top in class in the wireless ANC headphones category. The sound quality is great, the noise cancelling is best in class, the call quality thanks to the six microphones and the processing is also best in class even with background noise.
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-022', 'sony-wh1000xm6', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/6a62162760b2e4025ae98358/null/6a62162860b2e4025ae98383/', 'CatboxFive', '2026-07-07', '{"value":4,"scale":5}'::jsonb, NULL, 'They weren’t cheap, but I managed to get them at a great price. They performed really well on the flight to Tunisia and are working equally well by the pool. Whilst they pack a punch in the bass department, they don’t block out every sound. That said, they reduce external noise enough that even low-volume music makes the background nearly unnoticeable.
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-023', 'sony-wh1000xm6', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/69c3e2a660b262705cbd0505/null/69c3e2a760b262705cbd0542/', 'nomukaiki', '2026-03-09', '{"value":3,"scale":5}'::jsonb, NULL, 'The sound quality on the Sony WH1000XM6 is good and overall they are pleasant to listen to, but there are a few things that really let them down for me. The biggest issue is the noise cancelling behaviour. Sometimes it seems to ease off or let sound through when it detects people speaking, train announcements, or similar sounds, even when I actually want those sounds cancelled. That becomes frustrating very quickly, especially in public transport. It would also help a lot if these features were easier to control in a more direct and simple way in the app. The multi device pairing sounds great on paper, but in practice it can be very annoying. If I am listening on one device or in the middle of a video call, and my phone rings, the sound from the call or media cuts out abruptly. Coming from Apple AirPods Max, that whole transition felt much better and less disruptive. Another thing I do not like is having to press the power button every time I want to use the headphones. I understand it is meant to save battery, but it makes the experience feel less seamless. Having a proper head sensor to automatically power on and off when you put them on or take them off would be much better. So…', true, 'Sometimes it seems to ease off or let sound through when it detects people speaking, train announcements, or similar sounds, even when I actually want those sounds cancelled.', NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-024', 'sony-wh1000xm6', 'retailer', 'Argos', 'https://www.argos.co.uk/product/7616497#reviews', 'Simon2012', '2026-09-23', '{"value":5,"scale":5}'::jsonb, 'Great Noise Cancelling Haeadphones', 'Bought these as a birthday present for my son. He loves them. Easy to connect to an IPhone and very comfortable. Great sound quality, long battery life and great noise cancelling. Quality pair of headphones.', false, 'Bought these as a birthday present for my son.', NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-025', 'sony-wh1000xm6', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/7616497#reviews', 'Helen29', '2026-09-21', '{"value":5,"scale":5}'::jsonb, 'Excellent quality', 'I was bought these as a gift a couple of months ago. I use them when on my rower, house work etc, i m not keen on wearing them when i walk because i like to be aware of my surrounding& they connect to my piano. I haven&#x27;t had to charge them yet, so battery life good. Noise cancellation is extremely good i ve never had such high quality earphones before. Comfortable to wear & sound quality is top rate. Fold up in storage case very pleased with them', false, 'I was bought these as a gift a couple of months ago.', NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
