INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-027', 'sony-wh1000xm6', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/7616497#reviews', 'star lord', '2026-09-09', '{"value":5,"scale":5}'::jsonb, 'Great purchase', 'I bought these a few weeks ago and they were great on the flight - especially given the number of small children also on the flight ... 🤣🤣', false, 'I bought these a few weeks ago and they were great on the flight - especially given the number of small children also on the flight ...', NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
