INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-029', 'sony-wh1000xm6', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/7616497#reviews', 'Chez_xox', '2026-09-02', '{"value":5,"scale":5}'::jsonb, 'Nice', 'Great headphones, excellent sound quality, lovely colour, good noise cancellation. The only thing I would have expected from Sony is to not have sound leaking from the headphones so that other people can hear what you’re listening to, that’s the only thing that lets this product down.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-030', 'sony-wh1000xm6', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/7616497#reviews', 'Dogs dad', '2026-08-30', '{"value":5,"scale":5}'::jsonb, 'Best I’ve ever had', 'Absolutely made up with these headphones, genuinely the best I’ve ever owned. The sound quality is fantastic, and you can personalise it exactly how you like. The features available through the app are brilliant and unlike anything I’ve seen on other headphones. I couldn’t be happier with them!', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-031', 'sony-wh1000xm6', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/7616497#reviews', 'John2556', '2026-08-28', '{"value":5,"scale":5}'::jsonb, 'Upgraded my CH700N phones', 'Noise cancelling exceeds expectations.  Traveled by train recently and frequently missed driver messages since they were filtered out.  Nothing urgent missed.  Sound was clear and very comfy to wear.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
