INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm6-033', 'sony-wh1000xm6', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/7616497#reviews', 'Dolcé Tortà', '2026-08-17', '{"value":5,"scale":5}'::jsonb, 'A lovely upgrade from the XM5', 'So, as someone who had the previous version, the WH-1000XM5, for a couple of years, I decided it was finally time for an upgrade and treated myself to the WH-1000XM6 in this absolutely gorgeous khaki colour!
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-001', 'sony-wh1000xm5', 'pro_review', 'What Hi-Fi?', 'https://www.whathifi.com/reviews/sony-wh-1000xm5', 'What Hi-Fi?', '2022-10-20', '{"value":5.0,"scale":5.0}'::jsonb, 'Sony WH-1000XM5 wireless headphones review: outstanding sonics and ANC | What Hi-Fi?', 'What Hi-Fi? Awards 2024 winner. New design, same result for Sony’s superb premium noise-cancelling headphones […] We originally reviewed the Sony WH-1000XM5 back in May 2022 and although they have now been superseded by the Sony WH-1000XM6 , the XM5 remain a highly recommendable pair of wireless headphones. Shop around online and your''e likely to find a discount which makes their engaging sound quality, impressive noise-cancelling, great call quality and comfortable fit a match for any rival at the money. Our original review of the Sony WH-1000XM5 is presented below. […] Bluetooth SBC, AAC, LDAC Battery life 30hrs Charging USB-C Transparency mode Yes Built-in mic and controls Yes Finishes Black, Platinum Silver, Midnight Blue, Smoky Pink Weight 250g […] In recent years, Sony has struck upon a winning formula that has seen it build some of the best noise-cancelling headphones on the market. Each iteration has looked pretty similar to the last but it has been the gradual improvements in sound quality, noise-cancelling and call quality that have kept the WH-1000 line of headphones one step ahead of the competition.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-002', 'sony-wh1000xm5', 'pro_review', 'The Verge', 'https://www.theverge.com/23067645/sony-wh-1000xm5-noise-canceling-headphones-review', 'Chris Welch', '2022-05-12', '{"value":8.0,"scale":10.0}'::jsonb, 'Sony WH-1000XM5 review: new design, new sound, new price | The Verge', 'Familiar features packaged in a completely new design. […] Sony stuck with the same QN1 noise cancellation processor for the new headphones, but now it’s also added in a second processor to dial up ANC even further. As a result, the company says noise cancellation performs similarly to the M4s on a plane but should be better at handling street noise and cutting down on nearby voices. That’s been true in my experience. It’s still not enough to completely silence the world if you’re in a busy coffee shop, but it’s an improvement over what was already fantastic noise cancellation. […] This style looks more refined and cleaner with fewer obvious seams and such. The mic inlets that looked like USB-C ports on the previous model are gone, now located around the perimeter of the headphones and set deeper to help cut back on wind noise. The ear pads are a bit wider and more memory foam-y, which results in improved overall comfort. Even with the revamped design, the M5s weigh in at 250 grams, pretty much the same as the 254-gram M4s. Sony continues to offer them in black or off-white, and the latter has a subtle textured finish that hides finger oils and smudges better than the black model.…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-003', 'sony-wh1000xm5', 'pro_review', 'Trusted Reviews', 'https://www.trustedreviews.com/reviews/sony-wh-1000xm5', 'Kob Monney', '2024-06-12', '{"value":5.0,"scale":5.0}'::jsonb, 'Sony WH-1000XM5 review: Noise cancel culture', 'With a new design, improvements to the audio and the ever-reliable ANC and ambient sound modes, Sony''s WH-1000XM5 is another great headphone […] Editorial independence means being able to give an unbiased verdict about a product or company, with the avoidance of conflicts of interest. To ensure this is possible, every member of the editorial staff follows a clear code of conduct. […] The space for your ears has taken on a rounded shape, which Sony says is based on its research of people’s ears. However, while I could wear these headphones for hours, they don’t feel as comfortable as the Sonos Ace . Dekoni offers earpads you could use in place of the ones Sony offers, with leather and suede options available. […] Battery life is 30 hours of noise cancellation, and a two-hour battery drain saw them drop to 93%, so thirty hours is possible at about 50% volume. Turn noise cancelling off and there’s a boost from 38 to 40 hours over the previous model. […] Sony’s WH-1000XM5 improve over their predecessors where it counts. The rich but detailed sound impresses, the noise-cancelling is strong, the call quality is superb; and the range of features and customisation they offer is unmatched.…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-004', 'sony-wh1000xm5', 'pro_review', 'Tom''s Guide', 'https://www.tomsguide.com/reviews/sony-wh-1000xm5', 'Simon Lucas', '2022-05-12', '{"value":4.5,"scale":5.0}'::jsonb, 'Sony WH-1000XM5 review | Tom''s Guide', 'Stellar performance and features in a sleeker flagship design […] The earcups are of sensible dimensions, so unless your ears are (to be blunt) extravagantly large they should fit nicely. Unlike quite a few alternative designs, the Sony won’t swamp those among us with smaller heads, either. But while they’re unarguably comfortable, the composition of materials in the earpads seems to return your body-heat — with interest — rather quicker than some rival designs. […] Price: $399 / £379 / AU$649 Colors: Black; silver; midnight blue Battery life (rated): Up to 40 hours; 30 hours (ANC enabled) Connectivity: Bluetooth 5.2 with SBC, AAC and LDAC Water resistance: Not specified Weight: 8.8 ounces […] The WH-1000XM5 have a total of eight mics, and as well as noise-cancelation and telephony, they’re also involved in voice-assistant interaction. Naturally the Sony will work with your source player’s native voice-assistant, but they also have Amazon Alexa built in. And no matter your voice-assistant of choice, the Sony are able to communicate with them clearly and consistently. OK Google with full wake-up word detection is very well implemented, which puts them clear of quite a lot of their n…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-005', 'sony-wh1000xm5', 'pro_review', 'The Indian Express', 'https://indianexpress.com/article/technology/sony-wh100xm5-real-world-long-term-review-8398669/', 'Vivek Umashankar', '2023-01-23', NULL, 'Sony WH-1000XM5 long-term review: The best headphone for frequent fliers | Technology News - The Indian Express', 'Here is my recent experience with the Sony WH-1000XM5, which is among the best over-the-ear noise cancellation headphones in the world. […] During my regular testing, I liked the noise cancellation capabilities of the WH-1000XM5 and how comfortable they were with day-to-day usage . And while I regularly used the WH-1000XM5 in my house to block road noise, I didn’t appreciate it unless I turned on ANC on the headphone inside a flight. […] One can argue that most TWS can do all these things at a much lower price. But I feel that TWS earphones are not as comfortable as over-the-ear headphones, primarily because they sit inside the ear canal. On top of that, the Sony WH-1000XM5 also offers excellent battery life and could easily last for an entire trip on a single charge. More importantly, it can be fast-charged using a USB Type-C cable. […] Sony introduced its flagship WH-1000XM5 over-the-head active noise-cancellation headphones in September 2022 in India for Rs 34,990. And yes, we loved these headphones in our official review, and that’s also why we rated these as the best headphones for 2022. Right now, Sony’s WH-1000XM5 is available for just around Rs 27,000 as part of the ongoing…', true, 'And while I regularly used the WH-1000XM5 in my house to block road noise, I didn’t appreciate it unless I turned on ANC on the headphone inside a flight.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-006', 'sony-wh1000xm5', 'other', 'GymCaddy (blog)', 'https://www.gymcaddy.net/fitness-product-review/2024/3/4/bose-qc-ultra-amp-bose-qc-vs-sony-1000xm5-amp-sony-1000xm4-airplane-anc-test', 'Alexis Herrera', '2024-03-04', NULL, 'Bose QC Ultra & Bose QC Vs Sony 1000XM5 & Sony 1000XM4 Airplane ANC Test — GYMCADDY', 'So plainly said, yes both of Sony’s premium ANC headphones block out more noise than Bose’s new ANC headphones… those atmospheric pressure sensors in these headphones really give Sony’s headphones a big advantage over Bose’s headphones while at cursing altitude. And plainly said, if you want to block out the absolute most amount of noise while flying, the Sony 1000XM5’s are still the way to go. […] So in this video we’re going to compare the active noise cancelation performance while at cruising altitude on the Bose QC Ultra, and Bose QC, versus the Sony 1000XM5’s and Sony 1000XM4’s. Now its very important to point out that these ANC test were taken while at cruising altitude cause the atmospheric pressure change affects the overall ANC performance on these headphones when compared to ground level. […] However, personally I dont like flying with the Sony 1000XM5’s cause their carrying case is very large when compared to these other headphones, and when im flying space in my back pack or carryon is very valuable. Plus, the 1000XM5’s shallower ear cups aren’t as comfortable as these other headphones and their more spacious ear cups. […] Peronsally, if I had to choose from this line u…', true, 'However, personally I dont like flying with the Sony 1000XM5’s cause their carrying case is very large when compared to these other headphones, and when im flying space in my back pack or carryon is very valuable.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
