INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-016', 'sony-wh1000xm5', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/69c3e2e760b262705cbd355e/null/69c3e2e760b262705cbd35ab/', 'Sheriffu', '2026-03-07', '{"value":5,"scale":5}'::jsonb, NULL, 'he Sony WH‑1000XM5 (WH-1000XM5) are premium wireless headphones offering industry-leading noise cancellation, high-resolution sound quality, and strong comfort for everyday use such as travel, work, gym, and entertainment. This version is identical to the standard model but comes with a soft carrying case instead of a hard case. Key highlights include advanced noise cancellation with eight microphones, 30-hour battery life with quick charging, clear call quality using AI voice pickup, and multipoint Bluetooth connection for two devices. The headphones also provide soft-fit leather ear pads for long-term comfort, plus smart features through the **Sony | Sound Connect app, such as adaptive sound control, customizable EQ, and voice assistant support.', false, NULL, NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-017', 'sony-wh1000xm5', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/6a07161c60b29fe5b89caa3d/null/6a07161c60b29fe5b89caa89/', 'rmunir', '2026-04-23', '{"value":1,"scale":5}'::jsonb, NULL, 'I bought these in July 2025, expecting "industry-leading" quality for a premium price. Less than a year later, the slider arm has already snapped during normal use.
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-018', 'sony-wh1000xm5', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/69988c3060b2cac94054f11d/null/69988c3060b2cac94054f16e/', 'flyawayhome', '2025-12-27', '{"value":5,"scale":5}'::jsonb, NULL, 'These are hands-down the best headphones I have ever bought. I am a musician and music producer, so would say I have a sensitive ear to sound quality. The bass is superbly clean, and the trebles are so crisp, it’s like sitting in a room watching a live performance of the artist. The touch screen functions are incredible - the entirety of the right flat side is a touch board! Volume, skipping a track, and more. I love the speak-to-chat function, where your music stops playing momentarily if you are talking, then has a gradual fade when you stop talking in so it doesn’t jolt you. The Sound Connect App allows you to change the EQ in many different ways! So great. Call quality is very crisp; there is just the slightest static to the receiving end. The build and comfort is phenomenal - so soft, cushy, and secure. I got the Midnight Blue, and it looks like a designer pair of headphones! In love. Thank you so much, Sony!', false, NULL, NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-019', 'sony-wh1000xm5', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/696f952360b2805c369a359f/null/696f952460b2805c369a35f4/', 'Sakshi 357', '2026-01-15', '{"value":5,"scale":5}'::jsonb, NULL, 'These were great when I bought them months ago, but they became lifesavers on an 11-hour flight next to a crying toddler (10 hours of nonstop crying, no exaggeration). Noise cancellation: 10/10. Battery life: amazing. Comfort: bonus win. Thanks to these, I enjoyed my K-drama and kept my sanity. Highly recommend.', false, 'These were great when I bought them months ago, but they became lifesavers on an 11-hour flight next to a crying toddler (10 hours of nonstop crying, no exaggeration).', NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-020', 'sony-wh1000xm5', 'retailer', 'Sony UK Store (Feefo)', 'https://www.feefo.com/reviews/sony-europe/6a6215ff60b2e4025ae97444/null/6a6215ff60b2e4025ae97462/', 'Brenda88', '2026-07-09', '{"value":2,"scale":5}'::jsonb, NULL, 'I really wanted to love these, in fact I ordered, reordered, and returned two different colourways. In the end I returned them because a) they are far to large for my head, even on the smallest setting and b) aesthetically the colourways are very ''''cold" and don''t suit my warm colouring, and c) the touch controls are on the right hand side only, making it awkward to use whilst doing right handed activites. The shape of the earphones meant that the lowest point would sit right on my jawline. I consider myself to have a fairly big round head (!) but it feels like these were really designed for men, without much thought for smaller women''s bodies. The aesthetic point isn''t something I would normally worry about too much, however for the price and prestige of these headphones I think you really have to love them to justify the cost. In the end I''ve opted for a pair of Anker noise cancelling headphones which share a lot of the same features, have a much warmer tone that suits my colouring, and most importantly - fit my head. They''re nowhere near as well designed or high quality as these Sony ones but having them not sit on my jaw is more important than the sound quality at this stage fo…', true, NULL, NULL, '2026-09-25', '["Feefo verification state: thirdPartyVerified","Collected by the manufacturer’s own store (Sony), syndicated to Currys via Feefo"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-021', 'sony-wh1000xm5', 'retailer', 'Argos', 'https://www.argos.co.uk/product/2847319#reviews', 'Greentea', '2026-09-23', '{"value":5,"scale":5}'::jsonb, 'Noise cancellation at last.', 'Really pleased with this purchase. The noise cancellation is very impressive as ‘road tested’ on a recent flight to Southampton. Ear buds simply don’t work for me - must be my ear profile. Handy and secure carry case. It’s not cheap but it does exactly what it says on the tin. Money well spent if you can afford it.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
