INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-028', 'sony-wh1000xm5', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/2847319#reviews', 'NitinK', '2026-08-24', '{"value":3,"scale":5}'::jsonb, 'Its an ok product', 'I bought this 2 weeks ago and do not agree with all the hype this product have.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-029', 'sony-wh1000xm5', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/2847319#reviews', 'therealedwin', '2026-08-20', '{"value":4,"scale":5}'::jsonb, 'XM5 bettered way more than my previous buys', 'The headphones are really comfortable. It&#x27;s cushions are super comfy and is very lightweight. The sound quality is very good but still can better on deep sound and those feeble notes. The noice cancellation is really good compared to the other headphones I used such as Bose QuietComfort 2 and Sennheiser HD450 BT. But I sometimes hate the app firmware issue where the settings get adjusted back to default for some reason. Although the Adaptive Sound Control feature is good, in my situation, the mode switched from noice cancellation to adaptive mode unnecessarily. And the packaging of the product is super premium. I loved the way the headphone reached me in a supergood case. I loved the colour also, the matte navy blue. Overall, it&#x27;s a really good buy.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (sony.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-xm5-030', 'sony-wh1000xm5', 'retailer', 'Argos (syndicated from sony.com)', 'https://www.argos.co.uk/product/2847319#reviews', 'Mighty mac', '2026-08-18', '{"value":5,"scale":5}'::jsonb, 'Sounds great', 'Received as a gift but Sony is my goto headphones normally inner ear headphones but these are as good 
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-001', 'bose-qc-ultra-2', 'pro_review', 'Trusted Reviews', 'https://www.trustedreviews.com/reviews/bose-quietcomfort-ultra-headphones-2nd-gen', 'Kob Monney', '2026-04-01', '{"value":4.0,"scale":5.0}'::jsonb, 'Bose QuietComfort Ultra Headphones (2nd Gen) Review - Trusted Reviews', 'The QuietComfort Ultra Headphones 2nd Gen gain some useful updates over the previous pair with increased battery life, improved sound and ANC […] And that’s not to say that the noise-cancelling performance hasn’t improved, but it’s a slight jump rather than a big leap. And compared to the Sony WH-1000XM6, I’d say the Sony edges it overall. […] Comfort is, as it’s always been with Bose headphones, excellent. Unlike the Sony WH-1000XM6 , which can crowd the ears a bit, there’s more space around the edges of the earcup and inside. […] The QuietComfort Ultra Headphones 2nd Gen gain some useful updates over the previous pair with increased battery life, improved sound and ANC but they are better-sounding and slightly better ANC efforts than Bose available for less money […] There are moments where the Bose don’t offer much of a defence against people’s voices and other moments where it’s resilient against them (certain voices evade the Bose’s microphones), and arguably the Bose QuietComfort Ultra Earbuds II are better on an aeroplane if you don’t mind the in-ear design.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-002', 'bose-qc-ultra-2', 'pro_review', 'WIRED', 'https://www.wired.com/review/bose-quietcomfort-ultra-headphones-2/', 'Ryan Waniata', '2025-10-23', '{"value":9.0,"scale":10.0}'::jsonb, 'Bose QuietComfort Ultra Headphones Gen 2 Review: Major Fun | WIRED', 'Bose’s best headphones add some convenient new tricks for a modest price rise. […] The orignal Bose QuietComfort Ultra headphones are aptly named, offering plush comfort, good sound, and the best noise canceling we’d ever tested upon their release. They stood as the unequivocal noise-canceling masters until Sony rivaled their dominance with the WH-1000XM6 , which brings new tech like a crazy-fast chipset to inch past the Ultra in some scenarios. […] Speaking of battery, there’s a slight boost from the original''s 24 hours to 30 hours of playback with noise canceling (24 with Immersive Audio). You can now listen while they charge and access lossless audio tracks over USB-C from supported sources, something neither the original Ultra nor Sony’s XM6 offer. […] Bose has also made it easier to control noise canceling and transparency modes, letting you switch off ambient audio completely in the app or customize how much sound is blocked or piped in from the microphones under Noise Control. Previously, this required creating a Custom sound mode.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-003', 'bose-qc-ultra-2', 'pro_review', 'What Hi-Fi?', 'https://www.whathifi.com/headphones/bose-quietcomfort-ultra-headphones-2nd-gen', 'Becky Roberts', '2025-11-26', '{"value":4.0,"scale":5.0}'::jsonb, 'Bose QuietComfort Ultra Headphones (2nd Gen) review: the best Bose ANC headphones to date | What Hi-Fi?', 'Can Bose compete with Sony, Sennheiser and B&W''s best? […] We wouldn’t be surprised if the words ‘long haul travel’ featured on the Bose’s designers mood board when creating the Ultra Headphones – bolded, underlined and capitalised. The earcups still fold inwards, allowing them to scrunch up in a generous-sized coat pocket or in the compact hard-shell carry case. And despite looking flimsier than some of their rivals, their build quality appears to stand the test of time; our sample of the original Ultra still look relatively new despite having been frequently used by our reviews team for two years. […] Bose’s best noise-cancelling over-ear headphones yet barely put a foot wrong when it comes to features and comfort, packing class-leading noise cancellation and a wealth of functionality into a smart, nicely fitting design. But despite improving on the original Ultra’s audio quality, the latest rivals from Sony, Sennheiser and Bowers & Wilkins have stormed ahead in the sound department, widening the margin and ultimately costing these sequels a fifth star. […] In our five-star review of the original Bose QuietComfort Ultra Headphones , we highlighted a few imperfections in their des…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-004', 'bose-qc-ultra-2', 'pro_review', 'Tom''s Guide', 'https://www.tomsguide.com/audio/headphones/i-tested-the-sony-wh-1000xm6-vs-bose-quietcomfort-ultra-2-for-6-months-and-theres-a-clear-winner', 'Tammy Rogers', '2026-01-28', NULL, 'I tested the Sony WH-1000XM6 vs Bose QuietComfort Ultra 2 for 6 months — and there''s a clear winner | Tom''s Guide', 'Which should you buy? […] Both are about as comfortable as the other, although Sony''s headband starts to dig in a little after many hours of listening. It does take many hours, though — like, tens. I felt it after wearing them nonstop during a particularly long work day. […] The Sony WH-1000XM6 sit at the top of the Sony headphones hierarchy with excellent noise canceling, supremely customizable sound, and 30 hours of battery life.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-005', 'bose-qc-ultra-2', 'pro_review', 'Pack Hacker', 'https://www.packhacker.com/travel-gear/bose/quietcomfort-ultra-headphones-2nd-gen/', 'Lauren Maternowski', '2025-12-10', '{"value":7.7,"scale":10.0}'::jsonb, 'Bose QuietComfort Ultra Headphones (2nd Gen) Review | Pack Hacker', 'The Bose QuietComfort Ultra combines lightweight comfort, intuitive controls, and a slim travel case—perfect for all-day use, with just average battery life. […] Comfort is one of those things you can’t fake in a pair of over-ear travel headphones . You notice it immediately on a long flight, during back-to-back Zoom meetings, or when you’re halfway through a playlist deep dive. After spending a lot of time wearing the Bose QuietComfort Ultra, we find ourselves appreciating how seamlessly they disappear on your head. Plush padding, a lightweight frame, and intuitive wear detection create an experience that feels pleasantly effortless—even when worn for hours at a time. […] The case included with the QuietComfort Ultra feels just as thoughtfully designed as the headphones themselves. It’s a structured hard shell with a slim, travel-friendly profile that disappears into a backpack more easily than many headphone cases we’ve tested. Even though it’s slightly taller than some alternatives, the slimmer, more compact silhouette makes it feel more packable overall. Inside, a soft felt lining adds a premium touch and gives the headphones a little extra cushioning when they’re bouncing arou…', true, 'It’s a structured hard shell with a slim, travel-friendly profile that disappears into a backpack more easily than many headphone cases we’ve tested.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-006', 'bose-qc-ultra-2', 'other', 'Loud and Wireless (blog)', 'https://www.loudnwireless.com/blog/gen-2-bose-qc-ultra-killed-the-market-vs-gen-1-wh-1000xm6-px7-s3-airpods-max', 'matthew tjen', '2025-09-27', NULL, 'Gen 2 Bose QC Ultra KILLED the market (vs Gen 1, WH-1000XM6, Px7 S3, AirPods Max) — Aaron x Loud and Wireless', 'They do cut a bit more noise in the low frequencies than the Px7 S3, the WH-1000XM6 and the AirPods Max, so they will perform better at cutting noise in general but especially the rumbling noise of a plane’s engine, should you be flying for business or leisure. Now, to be fair, all of them are fantastic noise cancelers, but the QC Ultra Gen 2 is, in my opinion, the best. […] In many ways, I do prefer how Gen 1 sounds, but if you want less bloat in the bass, more definition and gravity in the vocals, you may prefer Gen 2. But apart from that, for some who already have Gen 1, Gen 2 may look like a compelling upgrade if you want better mic pickup, a slight upgrade to noise canceling, USB-C audio, Cinema mode and longer battery.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-007', 'bose-qc-ultra-2', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/6a24e0d0e4b00bb301145426//6a5a40f9e4b04ddfbb41c617/', 'Jay B,', '2026-07-17', '{"value":4,"scale":5}'::jsonb, NULL, 'I already own Quiet Comfort Ultra headphones in the 1st generation, and decided to upgrade to this new format. These are excellent for noise cancelling, and connect very quickly to desktop pc, laptop, or iPad. 
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-008', 'bose-qc-ultra-2', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/69350979e4b0df8c5006c523//6957556be4b061a694370790/', NULL, '2026-01-02', '{"value":1,"scale":5}'::jsonb, NULL, 'Bought  them as a Xmas present  for my wife for our holiday  at Xmas. They keep stopping and I''m having to connect  back to her phone. Got fed up off doing this so I''m returning them when I get back home.. had to buy beat ear buds whilst away and she loves them. So to me not good at all the bose ones', false, 'Bought  them as a Xmas present  for my wife for our holiday  at Xmas.', NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
