INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-010', 'bose-qc-ultra-2', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/6a3757b3e4b0a761b29f959f//6a54887ae4b00fdc4813f100/', NULL, '2026-07-13', '{"value":5,"scale":5}'::jsonb, NULL, 'Bose are the best for noise cancellation, good sound quality, not necessarily the best. Structure could of been better to gain 5 stars.', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
