INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-qcu2-027', 'bose-qc-ultra-2', 'retailer', 'Argos (syndicated from bose.com)', 'https://www.argos.co.uk/product/7271959#reviews', 'PJ Shields', '2026-08-22', '{"value":4,"scale":5}'::jsonb, 'Nearly perfect.', 'Everything perfect apart from the grip, kept sliding off my head and needed up giving them to my partner. Takes a while to get used to the touch slide volume control, sound is immaculate no matter what style you choose, plenty of options for use in the gym, at home or even running. This is where they let me down though as they do tend to slide about easily as the grip is not to tight at all. Can be very frustrating and annoying when running as opposed to the ear buds which sit in perfectly.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (bose.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-001', 'sennheiser-momentum-4', 'pro_review', 'What Hi-Fi?', 'https://www.whathifi.com/reviews/sennheiser-momentum-4-wireless', 'What Hi-Fi?', '2022-08-08', '{"value":5.0,"scale":5.0}'::jsonb, 'Sennheiser Momentum 4 Wireless headphones review: great-value contenders | What Hi-Fi?', 'Same old supreme Sennheiser sound in a great-value package […] However, this is what comes before the theatrical ‘but’ from a judge delivering a positive verdict in a Hollywood court drama. Because that first-impression dissatisfaction is thankfully made up for by everything else these new Sennheiser headphones are and do. […] This touch-first design means on-cup buttons are few. In fact, there is only one: the combined power and pairing key features on the right earcup alongside a USB-C socket and five battery LED indicators. We admit that the Momentum 4 Wireless’s design has mostly been well thought out – even if we still wish it had some of the aesthetic pizazz of previous Momentums and, also, their folding earcups for easier storage. The earcups simply swivel flat to fit in the case or sit more comfortably when around a neck, which is practical but not as practical as being able to fold them inwards into a ball and shove them in a coat pocket. […] Another illustration of how competitive Sennheiser is being is how many headlines it has packed into the Momentum 4 Wireless’s spec sheet. It’s difficult to look past the claimed 60-hour battery life, which isn’t only possible when th…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-002', 'sennheiser-momentum-4', 'pro_review', 'TechRadar', 'https://www.techradar.com/reviews/sennheiser-momentum-4-wireless', 'Becky Scarrott', '2022-08-24', '{"value":5.0,"scale":5.0}'::jsonb, 'Sennheiser Momentum 4 Wireless review: better than the Sony WH-1000XM5 | TechRadar', 'Sennheiser’s fourth-generation cans shine sonically, despite their plain looks […] Rarely have we only had to juice up our cans once and once only during testing, but here the Sennheiser just went on and on... and on, aided by wearer-detection to pause playback if you remove them and an automatic function which powers them off if they''ve been inactive for 15 minutes, to be roused by another touch. But if you do find yourself low on juice, wired listening is also an option, either using the bundled 2.5mm to 3.5mm audio cable or a USB-C to USB-C one (not supplied, although you do get a flight adapter and a USB-C to USB-A charging cable in the stylish hardshell fabric case). […] The only real design flourishes here are the fabric on the external aspect of the headband (available in two colorways) and Sennheiser''s trademark S-in-a-rectangle branding at the base of the headband. It''s demure to a fault, especially when those ear cups are devoid of any accent whatsoever – and it''s the reason we removed half a star from the rating here. But if you''ll only glance at the overall star-rating we awarded these excellent Sennheiser noise-cancelling over-ears, you''ll see we forgave it all… […] Th…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-003', 'sennheiser-momentum-4', 'pro_review', 'SoundGuys', 'https://www.soundguys.com/sennheiser-momentum-4-wireless-review-86111/', 'Christian Thomas', '2025-09-23', '{"value":8.0,"scale":10.0}'::jsonb, 'Sennheiser MOMENTUM 4 Wireless review - SoundGuys', 'The Sennheiser MOMENTUM 4 Wireless improves upon the last-gen headset, but does it keep up with other big hitters? […] Sennheiser has its tuning on lockdown and posts an excellent score for Timbre. Bass isn’t terribly overemphasized, and there are no real wild swings to note that would harm your experience. I did notice that they were better than average with their representation of 3D space in stereo mixes, and that’s reflected here as well. Overall, the Sennheiser MOMENTUM 4 Wireless sounds pretty good for this category. […] Inside the packaging of the Sennheiser MOMENTUM 4 Wireless is a fabric case with rigid plastic, an airplane adapter, a USB-A to USB-C cable, and a 2.5mm to 3.5mm TRS cable to use with sources that don’t have Bluetooth. While that’s quite a lot in the way of accessories, the carrying case has a mesh pocket, flexible loops, and ample room to store these comfortably. […] Back at the lab, we set the Sennheiser MOMENTUM 4 Wireless to run our standardized battery test of continuous music playback peaking at 75dB(SPL). The headphones last 56 hours and 21 minutes (with ANC on)—an exceptionally good result! As always, your mileage may vary depending on your use, but t…', true, 'I did notice that they were better than average with their representation of 3D space in stereo mixes, and that’s reflected here as well.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-004', 'sennheiser-momentum-4', 'pro_review', 'The Verge', 'https://www.theverge.com/23297129/sennheiser-momentum-4-wireless-headphones-review', 'Chris Welch', '2022-08-08', '{"value":7.0,"scale":10.0}'::jsonb, 'Sennheiser Momentum 4 headphones review: less cool, more comfortable | The Verge', 'A much more comfortable (but terribly generic) design. […] But they at least feel great on your noggin’. Sennheiser has matched Sony’s WH-1000XM5 in this department, which is no small feat. The Momentum 4s use artificial PU leather for the replaceable ear pads and headband padding, and both have ample cushioning. There’s not much clamping force to speak of, so they should remain comfortable on long flights or when you’re using them all day long at the office. […] An overhauled design prioritizes comfort over the retro looks of Sennheiser’s past Momentums […] Additionally, nearly all of the physical buttons have been removed in favor of tap and swipe gesture controls. And while some of the company’s fans will be repulsed by what I can only describe as a dull, uninspired look, there are at least some reasons to be excited about Sennheiser’s latest cans. Topping that list are improved noise cancellation and a remarkable 60 hours of promised battery life. […] There’s plastic everywhere — Sennheiser says there’s still metal reinforcing the headband — and they look like a mash-up of the company’s cheaper cans and something like the Microsoft Surface Headphones 2 . With outer ear cups tha…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-005', 'sennheiser-momentum-4', 'pro_review', 'Trusted Reviews', 'https://www.trustedreviews.com/reviews/sennheiser-momentum-4-wireless', 'Kob Monney', '2024-06-26', '{"value":4.5,"scale":5.0}'::jsonb, 'Sennheiser Momentum 4 Wireless Review', 'An excellent pair of wireless headphones that deliver a balanced, neutral presentation, long battery life and very good noise cancellation […] Editorial independence means being able to give an unbiased verdict about a product or company, with the avoidance of conflicts of interest. To ensure this is possible, every member of the editorial staff follows a clear code of conduct. […] The synthetic leather earpads are cushy, offering a supple contact area that makes wearing these headphones for both short and extended periods very comfortable. The oval-shaped earcups present a large space for your ears – the Momentum 4 Wireless slip on like a comfortable pair of glass slippers. […] An excellent pair of wireless headphones that deliver a balanced, neutral presentation, long battery life and very good noise cancellation. The Sennheiser Momentum 4 Wireless all-round performance is excellent though the Sony WH-1000XM5 are better in most respects, and available for similar money […] It’s a clever if not the quickest mode of operation unlike the slider on Microsoft’s Surface Headphones 2 or B&O’s H95. Skipping tracks can take a few attempts too, so while it’s nice for Sennheiser to think ou…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-006', 'sennheiser-momentum-4', 'pro_review', 'Engadget', 'https://www.engadget.com/sennheiser-momentum-4-review-140004906.html', NULL, '2022-08-23', NULL, 'Sennheiser Momentum 4 review: Stellar sound, insane battery life', 'Sennheiser''s Momentum 4 headphones offer great sound alongside improved noise cancellation and jaw-dropping 60-hour battery life. […] When it comes to ANC performance, Sennheiser has made a big improvement. The noise cancellation on previous models was fine, but it didn''t come anywhere close to what Bose and Sony offer on their flagship headphones. With the Momentum 4, Sennheiser has narrowed the gap, especially with constant noise sources like sound machines and dishwashers. Bose and Sony are still better at blocking unwanted clamor overall, but the change from the Momentum 3 is obvious once you try this new version. […] When a company has been making headphones as long as Sennheiser has, you begin to expect certain things from it. In this case, that list includes class-leading sound quality and a comfy fit. What I don''t usually expect is jaw-dropping battery life and conveniences that typically only Sony manages to offer. […] For calls, Sennheiser has equipped the Momentum 4 with two beamforming microphones per side. Much like the ANC, the headphones do a better job blocking constant noise during calls than things like background music or television. The person on the other end c…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
