INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-010', 'sennheiser-momentum-4', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/69b625bce4b0bf2c74fb36b0/null/69d8c46de4b0d0283f38e74f/', NULL, '2026-04-10', '{"value":5,"scale":5}'::jsonb, NULL, 'These were bought for my daughter’s birthday. Absolutely loves them. Impressed with the noise cancellation and sound quality.', false, 'These were bought for my daughter’s birthday.', NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-011', 'sennheiser-momentum-4', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/68e8eb1ae4b0a9102af66cbf//6905c1eae4b02c6469e60eeb/', NULL, '2025-11-01', '{"value":4,"scale":5}'::jsonb, NULL, 'One criticism of the headphones is that they are large and fall from my head. I can make them a larger fit but not a smaller one. Quite annoying if you want to move around whilst wearing them', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-012', 'sennheiser-momentum-4', 'retailer', 'Argos', 'https://www.argos.co.uk/product/1488566#reviews', 'ksp', '2026-08-28', '{"value":5,"scale":5}'::jsonb, 'Excellent office headphones', 'The noise cancelling is great for the office and easy to control through the app. It&#x27;s made Teams calls much easier. The microphones are great, very clear in calls apparently. Sound quality for listening to music is excellent too and they connect very easily to my laptop via Bluetooth. Love that they pause music automatically when you take them off, and then turn off after a while when not in use. Makes the battery last so much longer than my old headset. Also the most comfortable headphones, fantastic for wearing all day.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-013', 'sennheiser-momentum-4', 'retailer', 'Argos (syndicated from Sennheiser)', 'https://www.argos.co.uk/product/1488566#reviews', 'M Gomes', '2026-08-06', '{"value":1,"scale":5}'::jsonb, 'Not great, very unreliable', 'I am a professional videographer and have used Senheiser products for 30 years, from mics to headphones. I purchased a pair of Momentum 4 SE for my video editing work. However 9 months in and the ANC function failed. I sent them back for a warranty repair and after 3 months I have no idea where my headphones are, I can no longer recommend Senheiser as a professional company and will look to move to Rode,Sony or Bose for my professional work.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (Sennheiser) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-014', 'sennheiser-momentum-4', 'retailer', 'Argos', 'https://www.argos.co.uk/product/1488566#reviews', 'James65', '2026-07-10', '{"value":4,"scale":5}'::jsonb, 'Uncomfortable', 'I bought these headphones a week ago, having seen good reviews. The sound is great and I have no issues with that. Noise cancelling is adequate and I have just one major gripe. I had read that these headphones were comfortable for large head sizes and this was a big contributor to why I purchased them. So let me make this quite clear, they are NOT comfortable for larger heads, in fact they are painful on my ears and much worse than the pair I used for the last year or so. In conclusion, only get these of your head is small to medium and avoid the pain.', false, 'I had read that these headphones were comfortable for large head sizes and this was a big contributor to why I purchased them.', NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-015', 'sennheiser-momentum-4', 'retailer', 'Argos', 'https://www.argos.co.uk/product/1488566#reviews', 'Marcin', '2026-05-24', '{"value":5,"scale":5}'::jsonb, 'Awesome headphones', 'I bought this headphones few months ago, they really good, powerful and well designed. Noise cancellation is top notch. Battery last for long time even with intensive use. Recommend this to my brother and he is pleased as well. Definitely worth buying.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-016', 'sennheiser-momentum-4', 'retailer', 'Argos', 'https://www.argos.co.uk/product/1488566#reviews', 'Amj777', '2026-05-15', '{"value":4,"scale":5}'::jsonb, 'Nice headphones', 'Bought these a few weeks ago and can honestly say they are a really decent pair of headphones.  I like that they are more bassy than others. The anc is good too. The battery lasts a long time so will not be charging these too much!  Overall I’m satisfied with these.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-017', 'sennheiser-momentum-4', 'retailer', 'Argos', 'https://www.argos.co.uk/product/1488566#reviews', 'Steady', '2026-05-13', '{"value":5,"scale":5}'::jsonb, 'Very practical', 'Excellent battery and practical design. Nice smart controls  feature and excellent sound clarity. Clear and crisp,  great sound so long as you don&#x27;t want too much low end.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\""]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
