INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-m4-021', 'sennheiser-momentum-4', 'retailer', 'Argos', 'https://www.argos.co.uk/product/1488566#reviews', 'Dust3r', '2026-04-17', '{"value":4,"scale":5}'::jsonb, 'Great for the price range', 'Soundstage and detail is what you expect from Sennheiser. Definitely use the companion app to refine sound and functions. Graphic equalizer and bass boost button. ANC not particularly special but acceptable when listening to music. I’ve heard a few complaints about comfort, I have a relatively large head&#x2F;ears but when head band is adjusted suitably adjusted can where comfortably for 5hrs +
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-001', 'bose-quietcomfort', 'pro_review', 'Tom''s Guide', 'https://www.tomsguide.com/reviews/bose-quietcomfort-headphones', 'Alex Bracetti', '2023-10-18', '{"value":4.0,"scale":5.0}'::jsonb, 'Bose QuietComfort Headphones review: A QC45 upgrade with better sound and battery life | Tom''s Guide', 'Looking like a refreshed QC45, the new design has enough to impress […] I’ve used the QC Headphones when working from home during what has been an endless construction project outside of my apartment. They completely silenced the drilling noises. Other outdoor disruptions went unnoticed (e.g., barking dogs, chatty pool-goers, landscaping), along with my son’s loud cries and my wife’s speakerphone conversations. Wind Block decreased the wind presence in gusty conditions. High-frequency sounds occasionally entered the soundscape, but it was mostly blaring noises like fire alarm sirens and whistles. Overall, the QC Headphones eliminated noise at the same level as their predecessor. […] Billed as the successor to the QuietComfort 45 that launched at $329 in 2021, the new QuietComfort Headphones have been quietly ushered in and boast many of the same hallmarks including companion app support with personalization, excellent active noise cancellation , and fantastic comfort. On top of that, they welcome improved sound along with several other updates in a modernized design — don''t forget to check out our Bose QuietComfort Headphones vs. Bose QuietComfort 45 for a full side-by-side breakdo…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-002', 'bose-quietcomfort', 'pro_review', 'PCMag UK', 'https://uk.pcmag.com/headphones/148808/bose-quietcomfort-headphones', 'Tim Gideon', '2023-09-25', '{"value":4.0,"scale":5.0}'::jsonb, 'Bose QuietComfort Headphones - Review 2023 - PCMag UK', 'Impressive noise cancellation with natural sound […] To uncover these changes, I A-B tested the QC 45 and the QC Headphones with the same set of tracks. Indeed, there is a notable difference. What stood out most plainly was the older model''s more prominent sculpting in the highs. Cymbals and higher-register strings sound brighter, though not necessarily more detailed. By contrast, the QuietComfort Headphones sound more full-bodied and rich. They also have a crisp, high-frequency delivery but sound more natural overall. That said, if you prefer a brighter audio signature, you can easily get close to the QC 45’s sound by boosting the treble via the in-app EQ. […] The Bose QuietComfort Headphones offer excellent active noise cancellation and a refined audio signature in a comfortable fit. […] The tactile on-ear controls are sensibly organized and easy to operate. The right earcup’s side panel has an array of three buttons. Tap the center button once to play or pause, twice to skip forward a track, and three times to go to the previous track. This multifunction button also handles too many call actions to list here, including everything from setting up a conference call to muting your…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-003', 'bose-quietcomfort', 'pro_review', 'SoundGuys', 'https://www.soundguys.com/bose-quietcomfort-headphones-review-99695/', 'Christian Thomas', '2025-03-31', '{"value":7.5,"scale":10.0}'::jsonb, 'Bose QuietComfort Headphones review - SoundGuys', 'Replacing the older QuietComfort 45 headphones the new Bose QuietComfort Headphones don''t come with many new tricks. […] Inside the box, the Bose QuietComfort Headphones come with a travel case, a 3.5mm to 2.5mm TRS cable , a USB type A to C cable, and some documentation. Unfortunately, an airplane adapter is not included, but that’s fine since most airlines have been steadily updating their in-flight entertainment systems. […] With high Timbre, Distortion, and Immersiveness scores, the Bose QuietComfort Headphones are about as crowd-pleasing as they come. It’s no surprise that a high overall MOS results from running the table with well-received performance. However, we have a theory that this is mainly due to high levels of bass that might be too much for many users who are older, or simply don’t like to be rattled like that. […] Everything, from the material choices to the placement of the microphones and buttons, are pretty much exactly the same as its predecessor — though that’s not a bad thing. After all, Bose’s last-gen headphones were comfortable to wear, and trying to fix what isn’t broken is a fool’s errand. The ear cups are large (63 x 40 mm), distribute their lightweight…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-004', 'bose-quietcomfort', 'pro_review', 'Android Police', 'https://www.androidpolice.com/bose-quietcomfort-headphones-review/', 'Ara Wagoner', '2024-02-01', '{"value":8.0,"scale":10.0}'::jsonb, 'Bose QuietComfort Headphones review: Second verse, same as the first', 'The Bose QuietComfort Headphones don''t shuffle, just repeat one […] Despite not being quite as plush as the QuietComfort Ultra''s headband, I''ve actually found the regular QuietComfort''s headband to be a more comfortable fit for hours and hours of listening. The band also stays put a bit better, allowing me to headbang to the music while the QuietComfort Ultra and Bowers & Wilkins Px7 S2 slid off my head down to the floor. […] Bose claims 24 hours of battery life while ANC is on, but I found myself sometimes getting 30 hours at times. Even when the headphones hit 20% or 10% around lunch after not being charged a couple days, I could listen for the whole afternoon before charging back up during dinner. The battery may not reach full as quickly as the previous generation, but the battery also seems slightly larger this generation compared to the 20-22-hour battery life on the QC 45.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-005', 'bose-quietcomfort', 'pro_review', 'Trusted Reviews', 'https://www.trustedreviews.com/reviews/bose-quietcomfort-headphones', 'Kob Monney', '2025-07-29', '{"value":4.0,"scale":5.0}'::jsonb, 'Bose QuietComfort Headphones Review: Cushy Comfort', 'The Bose QuietComfort Headphones are a solid pair of noise-cancelling headphones that feature sound better than the previous model […] Neither headphones sound dynamic but the QuietComfort Headphones achieve a better balance overall, and that brittle sound of the QC45 is replaced with a warmer, more mainstream one. It’s an improvement for sure, though it doesn’t put these Bose among the best wireless headphones for sound. […] A solid enough pair of noise-cancelling headphones that feature a better sound than the previous model. The Bose QuietComfort Headphones are also one of the most comfortable headphones to wear for travel, though the call quality performance is bafflingly strange. […] Bose claims up to 24 hours of battery life with the QuietComfort Headphones, which is the same as the QuietComfort 45. […] What’s strange about the QuietComfort Headphones, and I’ve said this about other Bose headphones, is the call quality. It is odd.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-006', 'bose-quietcomfort', 'other', 'GymCaddy (blog)', 'https://www.gymcaddy.net/fitness-product-review/2024/3/4/bose-qc-ultra-amp-bose-qc-vs-sony-1000xm5-amp-sony-1000xm4-airplane-anc-test', 'Alexis Herrera', '2024-03-04', NULL, 'Bose QC Ultra & Bose QC Vs Sony 1000XM5 & Sony 1000XM4 Airplane ANC Test — GYMCADDY', 'So in this video we’re going to compare the active noise cancelation performance while at cruising altitude on the Bose QC Ultra, and Bose QC, versus the Sony 1000XM5’s and Sony 1000XM4’s. Now its very important to point out that these ANC test were taken while at cruising altitude cause the atmospheric pressure change affects the overall ANC performance on these headphones when compared to ground level.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
