INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-008', 'bose-quietcomfort', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/6959e021e4b045a4481bb071//697c3616e4b06e8e0bfafcda/', 'Jonathan', '2026-01-30', '{"value":5,"scale":5}'::jsonb, NULL, 'Great sound quality. Comfortable to wear. Charge lasts several days. Noise cancelling is very effective. Can''t hear the wife anymore. Marvelous.', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
