INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-011', 'bose-quietcomfort', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/6935089de4b0294fd1239d84/null/6958dae6e4b061a69456e2b8/', 'James', '2026-01-03', '{"value":5,"scale":5}'::jsonb, NULL, 'I looked at several brands before buying, tried them with various music. Was initially going to buy Sonos based on the fact I had Sonos speakers at home which are excellent and have the edge on Bose. However in terms of headphones the Bose win over the Sonos. Both excellent headphones but for me the clarity of all the tones was excellent. I spent about 2 hours listening to both sets of headphones before making my choice.', false, NULL, NULL, '2026-09-25', '["Feefo verification state: feefoVerified"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
