INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-018', 'bose-quietcomfort', 'retailer', 'Argos (syndicated from bose.com)', 'https://www.argos.co.uk/product/3244708#reviews', 'Saintsman15', '2026-09-11', '{"value":5,"scale":5}'::jsonb, 'Outstanding Noise Cancelling', 'The Bose QC Noise Cancelling Headphones are outstanding. The noise cancellation is incredibly effective, making it easy to focus on music, calls, or work without distractions. They are lightweight, comfortable to wear for hours, and deliver clear, balanced sound quality. The battery life is excellent, and the overall build feels premium. Highly recommended for anyone looking for comfort and top-tier noise cancellation.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (bose.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-019', 'bose-quietcomfort', 'retailer', 'Argos (syndicated from bose.com)', 'https://www.argos.co.uk/product/3244708#reviews', 'ssshhhhhh', '2026-09-09', '{"value":5,"scale":5}'::jsonb, 'Comfort and sound excellent', 'I hesitated for about a year before buying these headphones.  Mainly down to the price as this is a huge cost for me.    They are the best headphones I have ever had.  So comfortable and the sound is great.   They have changed my life really because I love being able to just enjoy my time with my music and audiobooks.   If you can afford preminum headphones these are a great choice.', false, NULL, NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (bose.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
