INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-bqc-025', 'bose-quietcomfort', 'retailer', 'Argos (syndicated from bose.com)', 'https://www.argos.co.uk/product/3244708#reviews', 'Dobbo265', '2026-08-03', '{"value":5,"scale":5}'::jsonb, 'Fantastic', 'We bought these for my wife and she absolutely loves them. Girlie pink, great comfort and the audio is awesome.', false, 'We bought these for my wife and she absolutely loves them.', NULL, '2026-09-25', '["Argos review pages state: \"Customers are incentivised to submit product reviews as part of a prize draw.\"","Syndicated from brand site (bose.com) via Bazaarvoice, not written on Argos"]'::jsonb) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-001', 'sonos-ace', 'pro_review', 'TechRadar', 'https://www.techradar.com/audio/headphones/sonos-ace-review', 'Matt Bolton', '2024-06-03', '{"value":4.0,"scale":5.0}'::jsonb, 'Sonos Ace review: amazing Dolby Atmos movie headphones, but not such a slam with music | TechRadar', 'A class-leader in some ways, but not the one that matters most […] There''s a great sense of connection between the front and sides in the spatial audio surround presentation, adding to that feeling of it being a soundscape, not just stereo with some head tracking. The Sonos Ace don’t handle height quite as convincingly as AirPods Max when watching the same Dolby Atmos source, but the Sonos Ace''s head-tracking is absolutely perfect, and surround effects overall are just sublime. I think they’re marginally behind AirPods Max, but are 95% of the way there, and basically as good as virtual surround gets in headphones currently. […] The Sonos Ace are more complicated than we expected. They''re my favorite headphones to date for movies, and their integration with Sonos Arc (and more soundbars to come) really pushes that forward. But they''re a step behind the premium competition when it comes to music, even though they''re still detailed, fun and energetic. We also found that some testers had comfort issues with them – but they''re beautiful, well-specced, and have some smart design features that will win over a lot of people. […] Sonos promises 30 hours of battery life over Bluetooth with a…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-002', 'sonos-ace', 'pro_review', 'Conde Nast Traveler', 'https://www.cntraveler.com/story/sonos-ace-headphones-review', 'Emily Price', '2024-06-11', NULL, 'Sonos Ace Headphones Review: The Audio Brand Delivers on Sound Quality, Style, and Comfort | Condé Nast Traveler', 'The long-awaited noise-canceling headphones deliver on sound quality, style, and comfort. […] Earlier this month, audio powerhouse Sonos debuted its very first pair of headphones . The $449 Sonos Ace connects to your device via Bluetooth 5.4 and offers 30 hours of battery power so it can last from takeoff to landing on even the world’s longest flights. If you forget to charge them before takeoff, the headphones can also regain three hours of battery life with just three minutes of charging, so you can be up and running before wheels up. […] Where the Ace really wins is with comfort. The headphones weigh in at just 11 ounces and were designed with comfort (and your hair) in mind. The company wanted to make sure you could not only wear the headphones for the duration of an eight-hour flight, but you could do so without taking your earrings out or worrying about what your hair was going to look like when you land.', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-003', 'sonos-ace', 'pro_review', 'Qantas Travel Insider', 'https://www.qantas.com/travelinsider/en/travel-tips/sonos-ace-headphones-review.html', NULL, NULL, NULL, 'Review: We tested the Sonos Ace noise-cancelling headphones | Travel Insider', 'Sonos have just launched their first set of noise-cancelling wireless headphones, so we put them to the travel test. Here’s our full review. […] At first glance, it’s clear the Sonos team took a minimalist approach to the Ace. The device (available in matte black or white) comprises a plush headband and two memory foam cups connected by a stainless steel rod. Tucked under the left cup is your power-and-bluetooth-connectivity switch and USB-C port, while the right cup houses a slidable toggle and button. Where some headphones in the market have gone all-in with swipe-y touch controls, these tactile buttons are reassuringly manual. The slider adjusts volume and skip songs, while the standalone button switches between Active Noise Cancellation and Aware modes (a function designed to filter through external sounds – handy for listening to announcements at the airport). […] From a wearing perspective, there’s no doubt they’re comfortable. Coming in at just 312 grams, they’re fairly lightweight and easy to adjust for width – there’s no presets, just a customisable glide, set and forget – with a close fit that resists most jostles and headshakes. At full battery, Sonos Ace lasts for 30 ho…', true, NULL, 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-004', 'sonos-ace', 'pro_review', 'What Hi-Fi?', 'https://www.whathifi.com/reviews/sonos-ace', 'What Hi-Fi?', '2024-06-03', '{"value":3.0,"scale":5.0}'::jsonb, 'Sonos Ace wireless headphones review: disappointing debuts | What Hi-Fi?', 'Do the first Sonos wireless headphones live up to the hype? […] The earpads use memory foam coated in a layer of vegan leather (polyurethane) that feels quite plush, although you get a bit more cushioning from the Sony and Apple models. The adjustable headband uses a firmer structure of the same materials, and we find them comfortable enough. […] Battery life is always a big deal, and you get 30 hours of playtime on the Sonos Ace, with Bluetooth and ANC turned on. In comparison, the Sony XM5 are also good for 30 hours, but the AirPods Max lag behind with just 20 hours while the Bose QuietComfort Ultra Headphones offer 24 hours. A fast charge function on the Sonos gives you three hours of juice from just a three-minute charge. […] The Sonos Ace use eight mics in total – four in each cup – that are used for ANC and to deliver clear voice quality for calls. During testing, which happened in a range of environments from the train to the London Underground to a busy pub environment, we found noise cancelling to be okay, but not up to the standards set by the Sony WH-1000XM5 and the Bose QuietComfort Ultra Headphones.', true, 'During testing, which happened in a range of environments from the train to the London Underground to a busy pub environment, we found noise cancelling to be okay, but not up to the standards set by the Sony WH-1000XM5 a', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-005', 'sonos-ace', 'pro_review', 'Trusted Reviews', 'https://www.trustedreviews.com/reviews/sonos-ace', 'Kob Monney', '2024-06-10', '{"value":4.0,"scale":5.0}'::jsonb, 'Sonos Ace Review - Trusted Reviews', 'It feels as if we’ve been writing about Sonos headphones for years. They’re finally upon us and they’re called the Sonos Ace. […] It’s on planes that I noticed more of a gap between it and the Bose headphones, the QuietComfort Ultra Headphones suppress cabin noise for a quieter experience. I also noted some minor distortion during the buffeting take-offs. Overall, the ANC is very good but short of the Sony WH-1000XM5 and Bose QuietComfort Ultra Headphones. […] Highs are conveyed with sharpness and brightness that I think is slightly better than either Sony or Bose with GoGo Penguin’s Erased by Sunlight; but where the Sonos Ace’s overall deficit shows is in its level of detail and definition. […] A very good first attempt at a pair of headphones from the Sonos, but the Ace are beaten in several areas by more experienced rivals. The levels of comfort and the TV Audio Swap feature are excellent, though the Ace doesn’t yet feel like it’s the complete package, especially for the high asking price. […] You can tell which earcup is left or right thanks to contrasting colours inside the earcups. It’s also simple to detach the earpads if you need to replace them. The battery inside can be r…', true, 'It’s on planes that I noticed more of a gap between it and the Bose headphones, the QuietComfort Ultra Headphones suppress cabin noise for a quieter experience.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-006', 'sonos-ace', 'pro_review', 'T3', 'https://www.t3.com/features/i-used-the-new-sonos-ace-headphones-on-a-14-hour-flight-heres-how-it-went', 'Mike Lowe', '2024-06-05', NULL, 'I used the new Sonos Ace headphones on a 14 hour flight – here''s how it went | T3', 'Sonos'' first-ever headphones are great for the home – but how do they handle travel? […] One of the biggest trials I''ve thrown at the Sonos Ace was taking them on a trip from London to Hong Kong and back – the return flight officially listed at 14 hours and 40 minutes by British Airways. Not the length of time you want to be stuck in a big metal tube with a pair of sub-par headphones, that''s for sure. […] On the particular Boeing 787-10 aircraft covering my route, that meant a fairly decent throng of engine sounds and background air hiss (albeit less than the 777 – which also serves this route). That became unnoticeable on this flight. Any air steward queries meant popping an earcup off – although I could have activated Ambient, the only other ANC option, which permits a frequency passthrough. All in all a decent performance. […] Here I''ll detail how the Sonos Ace''s comfort, design, durability, battery life, sound quality and travel case handled my epic long-haul trip. Has the wait been worth it and can Sonos'' first-ever headphones live up to the hype and come out on top? […] There was no threat to battery life either – the 30 hours on offer here would handle the LHR-HKG trip there…', true, 'One of the biggest trials I''ve thrown at the Sonos Ace was taking them on a trip from London to Hong Kong and back – the return flight officially listed at 14 hours and 40 minutes by British Airways.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-007', 'sonos-ace', 'pro_review', 'WIRED', 'https://www.wired.com/review/sonos-ace/', 'Parker Hall', '2024-06-03', '{"value":8.0,"scale":10.0}'::jsonb, 'Sonos Ace Review: The Most Comfortable Headphones for Travel | WIRED', 'Sonos, the king of whole-home audio is heading outside and already sits at the highest echelon of noise-canceling headphones. […] There are some fancy features I don''t use much of. Having Dolby Atmos and head-tracking integration are expected at this price, but it isn''t really that useful in most situations, especially for music (no matter how much Apple tries to push it on us ). It works well for streaming films on mobile when traveling. You get some sense of immersion, even when looking at such a tiny screen. Fancy features Sonos doesn''t offer include automatically adjustable ANC or transparency for things like big sirens, and it doesn''t have the same speak-to-chat (or cup your ear to pause) features as Sony. I rarely use those features except when ordering a drink on a plane or reviewing said headphones, so it doesn''t bother me. […] The fit is astonishingly comfortable, thanks to the Ace’s 11-ounce weight. and there''s an excellent design choice where the headband attaches to the ear cups. It links up at the center of the cup, which gives the headphones a nice, center-directed clamping force. This means less headband fatigue and better comfort when wearing glasses, something I ex…', true, 'I rarely use those features except when ordering a drink on a plane or reviewing said headphones, so it doesn''t bother me.', 'Verbatim excerpts (meta summary + selected paragraphs, joined with […]) from the full article', '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-008', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/feedback-on-my-sonos-ace-6931666', 'David66', '2025-10-30', NULL, 'Feedback on my Sonos Ace', 'Beautiful, sturdy headphones. The case is excellent. They''re intuitive to use and have excellent sound quality, even for an inexperienced ear like mine. The only thing I''m not so thrilled with right now is that the earcups make me sweat over time and cause some problems when wearing glasses: the earcups press hard, causing the arms to shift into an unnatural position and making it difficult to put my glasses back in place.I haven''t tried other headphones from the same family yet to see if I''d have the same problem with competing headphones.So I can say I''m very happy with my purchase: they''re just a stone''s throw away from excellence.', false, 'led with right now is that the earcups make me sweat over time and cause some problems when wearing glasses: the earcups press hard, causing the arms to shift into an unnatural position and making it difficult to put my ', NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-009', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/does-the-sonos-ace-still-have-anc-problems-due-to-high-pitched-sounds-2025-q4-6932008', 'Dave106', '2025-11-24', NULL, 'Does the Sonos Ace still have ANC problems due to high pitched sounds? (2025/Q4)', 'I’ve seen various posts stating that the Sonos Ace ANC exhibits various popping or crackling effects as a result of nearby high-pitched sounds like knives, forks and other cutlery banging together.Examples:https://en.community.sonos.com/headphones-229145/sonos-ace-crackling-static-popping-with-certain-sounds-issue-with-anc-6927617 https://en.community.sonos.com/headphones-229146/sonos-ace-feedback-over-bumps-6897038Has this been fixed?I understand the newer Firmware has greatly improved the ANC, but I can’t find a clear conclusion on this topic.', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-010', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/noise-cancelling-6930901', 'Tiptree 25', '2025-09-01', NULL, 'Noise cancelling', 'Im considering adding the Sonos noise cancelling headphones to my setup - mostly for me to listen to music but there are times when I want to watch TV and my wife doesnt want to listen !Can the headphones be used just in noise cancelling mode ? So no music - just nice and quiet ?', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-011', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/left-ear-fluttering-with-anc-on-its-like-driving-with-the-car-window-slightly-open-6933831', 'Jetmoo', '2026-05-05', NULL, 'Left ear fluttering with ANC on. its like driving with the car window slightly open.', 'Against my instincts due to the long works with the Sonos app and the history etc I purchased the Ace today in the airport. First use after updating to firmware 3.9.9 and the left ear is making a pulsing fluttering effect from the ANC. ANC switched off. No problem. It''s exactly like driving on the highway with the window cracked open and you get that resonance. In short the headphones are useless in this state. The ANC can''t be used so they are dud. Is there a fix?Impossible to return to the shop as it''s in the airport and I''ve flown to my destination. What didn''t I listen to my gut?Thanks.', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-012', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/sonos-ace-anc-pop-sounds-and-hinge-clicks-is-this-normal-6927519', 'Rawrvik', '2025-02-26', NULL, 'Sonos ace ANC pop sounds and hinge clicks? Is this normal?', 'Hi! Recently picked up the sonos ace and I’ve noticed some flaws….A really cool feature of the sonos ace ANC is how it turns off in low noise environments to reduce white noise. This is a great feature I think because I hate the white noise. However when the ANC kicks in, it sometimes makes a “pop” sound that can get a bit annoying. Is this normal for the headset? I notice it the most when I’m on my PC clicking the mouse, Also I’ve noticed a fair amount of clicking/poping sounds when moving around, the noises come from the hinge system as when I press on the headband the noises disappear. Very noticeable when running on a thread mil. Is this normal too?Both these issues are identical on both ears, which makes me think that it’s normal, just want to check if others have experienced the same :)Thanks for reading.', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-013', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/sonos-ace-crackling-static-popping-with-certain-sounds-issue-with-anc-6927617', 'jameskal811', '2025-03-02', NULL, 'Sonos Ace Crackling Static/Popping with certain sounds - issue with ANC', 'Hi all, anyone else hear have some Sonos Ace headphones and can test this for me? I have two Sonos Ace headphones (wife and I) and they both do it. They’re both brand new. Sonos have told me they’re both faulty and to return them both but I’m thinking it’s more of a widespread QC issue. Put volume low or even off, and test with both ANC on and also in Aware mode and get some cutlery and drop the cutlery into the cutlery draw so it lands on other cutlery. This noise seems to make the headphones make a loud crackling static noise. It’s not just with cutlery, it’s lots of other loud metal or clicking noises. It’s like the ANC can’t handle it. This is definitely a fault with the ANC on these headphones and needs to be fixed.the noise does not occur when audio mode is OFF, only ANC on and Aware.', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-014', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/headphone-case-quality-replacement-6930200', 'macca113', '2025-07-13', NULL, 'Headphone case quality & replacement', 'Has anyone else out there experienced issues with broken/jammed zipper on their Ace headphones case ???My case has the zipper broken and I have repeatedly contacted Sonos who have promised a replacement but are yet to supply. I have written many times and reply is very limited which has been frustrating.Very disappointing from a premium supplierDoes anyone know of a product that you can buy as to replace this case?', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-015', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/sonos-ace-headband-loose-part-6929711', 'Larskrimi1106', '2025-06-16', NULL, 'Sonos Ace headband loose part', 'So i got my Ace headset around January and have been absolute loving them, the ANC is super sweet and the sound too. about a month ago i slid my fingers across the headband and noticed there was a sharp bumb, still not sure what it is, as i dont really wanna take them apart. My question is, if this is reason to send them back, ive been very careful with them as its an expensive piece of electronic for me, and im afraid the sharp thing will eventually pierce the headband.', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-016', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/ace-headphone-cushions-6934003', 'BillyT', '2026-05-30', NULL, 'Ace Headphone cushions', 'I Love my Sonos Ace headphones . The sound quality is so good and they are so comfortable to wear .I use them 3-4 times a week for a year, but have just notice the headphone cushion is lifting on the front.The ear cushions are fine. Are Sonos prepared to set and behind their excelllent product and repair or replace!', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-017', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/sonos-ace-headphones-and-the-3-5mm-to-usb-c-cable-issue-6929285', 'Loshkai', '2025-05-24', NULL, 'Sonos Ace Headphones and the 3.5mm to USB-C Cable Issue', 'Have seen lots of comments on this. Purchase the Sonos Ace headphones for my wife last week at the airport, and when plugged in to watch a movie, the sound is barely heard. This is using the USB C to 3.5mm cable.  Good to know the issue isn’t isolated to me but not good to hear it might be a broader issue. Has a resolution been identified?  Thinking it will be easier just to get a refund and buy the Sony WX5’s as this is what I use and there has been no issues. Main reason I purchased the Sonos Ace was because the Sony WX5’s don’t bluetooth well to the Sonos Arc on my TV and Sonos advised there is a known issue with LG, so best to the buy the Sonos Ace headphones. Go figure...', false, 'Purchase the Sonos Ace headphones for my wife last week at the airport, and when plugged in to watch a movie, the sound is barely heard.', NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-018', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/poor-sound-quality-new-updated-ace-headphones-6931032', 'ewhiteme', '2025-09-11', NULL, 'Poor sound quality new updated Ace headphones', 'New. Adjusted. Updated. Compared to my Bose QC35 ll and Bose buds, sound disappointing. Fuzzy, compressed, poor base. Android phone. Sonos Arc.', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-019', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/problems-with-calls-6929704', 'Ozyez', '2025-06-15', NULL, 'Problems with calls', 'I have had a couple of SONOS ACE and they all have the same problem, the audio in the calls. When making calls people can''t hear me in the best way, it''s as if the microphones didn''t work the right way. The problems that the people I talk to mention to me is that they hear interference or that my voice is too low. I thought that with the new update this problem would be solved but no. I recently connected my SONOS ACE through the USB - C cable to my iPhone and the surprise was that the audio problem in the calls was solved, the people I talk to can hear me very well. My question is do you know how to fix this problem with the wireless connection? Or do you know if SONOS is working on fixing this problem? Does the same thing happen to you?', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-020', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/sonos-ace-crack-noise-when-moving-head-6930699', 'didis54', '2025-08-16', NULL, 'Sonos Ace crack noise when moving head', 'Hi, just bought the Sonos Ace today.when i wear them, even when shutdown or started, the left ear is doing like a crack noise everytime I move my head. This is very disturbing, is there something wrong I’m doing ? thanks', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-021', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/headphone-has-no-oomf-6933885', 'Blessed', '2026-05-13', NULL, 'headphone has no oomf', 'Just got my Sonos ace and the quality is great. Only problem is the sound is not loud enough for me. Any suggestions?', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-022', 'sonos-ace', 'forum', 'Sonos Community (official forum)', 'https://en.community.sonos.com/headphones-229145/sonos-ace-open-to-strangers-in-public-6930347', 'Soundsgreat', '2025-07-22', NULL, 'sonos ace open to strangers in public', 'Ive read a few things on how to stop people having access to my sonos while at home on wifi but why is there nothing when im out in public.  I was recently powering up my headphones and someone connected to them.and played their music.  Then I didn''t have access to play music until I was out of range from them.  I dont have multipoint access turned on.  This is a huge let down...what can I do?', false, NULL, NULL, '2026-09-25', NULL) ON CONFLICT (id) DO UPDATE SET product_id = EXCLUDED.product_id, source_type = EXCLUDED.source_type, source_name = EXCLUDED.source_name, url = EXCLUDED.url, author = EXCLUDED.author, date = EXCLUDED.date, rating = EXCLUDED.rating, title = EXCLUDED.title, text = EXCLUDED.text, truncated = EXCLUDED.truncated, reviewer_context = EXCLUDED.reviewer_context, excerpt_note = EXCLUDED.excerpt_note, collected_at = EXCLUDED.collected_at, provenance_signals = EXCLUDED.provenance_signals;
INSERT INTO reviews (id, product_id, source_type, source_name, url, author, date, rating, title, text, truncated, reviewer_context, excerpt_note, collected_at, provenance_signals) VALUES ('rev-ace-023', 'sonos-ace', 'retailer', 'Currys (Feefo)', 'https://www.feefo.com/reviews/currys/6a812aa9e4b02c4a00714e85//6aa8aef2e4b0507a16649278/', 'David', '2026-09-15', '{"value":3,"scale":5}'::jsonb, NULL, 'Sorry not for me. Ear cups got why too hot in less than 1 hour. Sound was good with good separation and mids were nice but the bass was ok for me, as I have never been into deep bass sounds.. 
